from __future__ import annotations

import argparse
import json
import sys
import urllib.request
from typing import Any

from common import dump_json, dump_text


CHROME_FOR_TESTING_URL = "https://googlechromelabs.github.io/chrome-for-testing/last-known-good-versions-with-downloads.json"
LEGACY_PLATFORM_ALIASES = {
    "Mac": ["mac-arm64", "mac-x64"],
    "Windows": ["win32", "win64"],
    "Linux": ["linux64"],
}


def version_tuple(value: str) -> tuple[int, ...]:
    return tuple(int(part) for part in value.split(".") if part.isdigit())


def fetch_last_known_good(timeout: int) -> dict[str, Any]:
    request = urllib.request.Request(CHROME_FOR_TESTING_URL, headers={"user-agent": "openclaw-cws-publisher/0.3"})
    with urllib.request.urlopen(request, timeout=timeout) as response:
        payload = json.loads(response.read().decode("utf-8"))
    if not isinstance(payload, dict) or not isinstance(payload.get("channels"), dict):
        raise ValueError("unexpected Chrome for Testing last-known-good response")
    return payload


def latest_release(releases: list[dict[str, Any]]) -> dict[str, Any]:
    stable = [release for release in releases if release.get("version")]
    if not stable:
        raise ValueError("no stable releases with versions found")
    return max(stable, key=lambda release: version_tuple(str(release["version"])))


def stable_channel(payload: dict[str, Any]) -> dict[str, Any]:
    stable = (payload.get("channels") or {}).get("Stable")
    if not isinstance(stable, dict) or not stable.get("version"):
        raise ValueError("Chrome for Testing feed did not include a Stable channel version")
    return stable


def expand_platforms(platforms: list[str]) -> set[str]:
    requested: set[str] = set()
    for platform in platforms:
        requested.update(LEGACY_PLATFORM_ALIASES.get(platform, [platform]))
    return requested


def chrome_downloads(stable: dict[str, Any], requested_platforms: set[str]) -> list[dict[str, Any]]:
    downloads = ((stable.get("downloads") or {}).get("chrome") or [])
    if requested_platforms:
        downloads = [item for item in downloads if item.get("platform") in requested_platforms]
    return downloads


def render_markdown(report: dict[str, Any]) -> str:
    lines = [
        "# Chrome Stable Release Check",
        "",
        f"Source: `{report['source']}`",
        f"Feed timestamp: `{report.get('feed_timestamp', '')}`",
        f"Stable: **{report['stable']['version']}**",
        "",
        f"Blockers: **{len(report['blockers'])}**",
        f"Warnings: **{len(report['warnings'])}**",
        "",
        "| Download platform | Version | URL |",
        "| --- | --- | --- |",
    ]
    for item in report["downloads"]:
        lines.append(f"| {item['platform']} | {item['version']} | {item['url']} |")
    lines.extend(["", "## Blockers"])
    lines.extend([f"- {item}" for item in report["blockers"]] or ["No blockers."])
    lines.extend(["", "## Warnings"])
    lines.extend([f"- {item}" for item in report["warnings"]] or ["No warnings."])
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description="Check current Chrome Stable from the Chrome for Testing last-known-good feed.")
    parser.add_argument(
        "--platform",
        action="append",
        default=[],
        help=(
            "Repeatable Chrome for Testing download platform, such as mac-arm64, mac-x64, linux64, win32, or win64. "
            "Legacy Mac/Windows/Linux aliases are accepted."
        ),
    )
    parser.add_argument("--min-milestone", type=int, help="Fail if any checked Stable milestone is older.")
    parser.add_argument("--tested-chrome-version", help="Chrome version used for local E2E; warns when behind latest Stable milestone.")
    parser.add_argument("--timeout", type=int, default=20, help="HTTP timeout in seconds.")
    parser.add_argument("--json-out", help="Optional JSON report output path.")
    parser.add_argument("--markdown-out", help="Optional Markdown report output path.")
    args = parser.parse_args()

    blockers: list[str] = []
    warnings: list[str] = []
    payload: dict[str, Any] = {}
    stable: dict[str, Any] = {}
    downloads: list[dict[str, Any]] = []

    try:
        payload = fetch_last_known_good(args.timeout)
        stable = stable_channel(payload)
        stable_version = str(stable["version"])
        stable_milestone = version_tuple(stable_version)[0]
        downloads = chrome_downloads(stable, expand_platforms(args.platform))
        if not downloads:
            blockers.append("no Chrome download entries matched the requested platform filter")
        if args.min_milestone and stable_milestone < args.min_milestone:
            blockers.append(f"Stable milestone {stable_milestone} is below required {args.min_milestone}")
    except Exception as exc:  # noqa: BLE001 - report feed failures as release blockers.
        blockers.append(f"failed to fetch Chrome Stable release data: {exc}")

    if args.tested_chrome_version and stable.get("version"):
        tested_milestone = version_tuple(args.tested_chrome_version)[0]
        stable_milestone = version_tuple(str(stable["version"]))[0]
        if tested_milestone < stable_milestone:
            warnings.append(
                f"local E2E used Chrome {args.tested_chrome_version}, behind current Stable milestone {stable_milestone}"
            )

    report = {
        "ok": not blockers,
        "source": CHROME_FOR_TESTING_URL,
        "feed_timestamp": payload.get("timestamp", ""),
        "stable": {
            "channel": stable.get("channel", "Stable"),
            "version": stable.get("version", ""),
            "milestone": version_tuple(str(stable.get("version", "0")))[0] if stable.get("version") else 0,
        },
        "tested_chrome_version": args.tested_chrome_version or "",
        "downloads": [
            {"platform": item.get("platform", ""), "version": stable.get("version", ""), "url": item.get("url", "")}
            for item in downloads
        ],
        "blockers": blockers,
        "warnings": warnings,
        "references": [
            CHROME_FOR_TESTING_URL,
            "https://chromiumdash.appspot.com/fetch_releases",
            "https://chromereleases.googleblog.com/",
            "https://developer.chrome.com/release-notes/",
        ],
    }
    if args.json_out:
        dump_json(args.json_out, report)
    if args.markdown_out:
        dump_text(args.markdown_out, render_markdown(report))
    print(json.dumps(report, indent=2, ensure_ascii=True))
    if blockers:
        sys.exit(1)


if __name__ == "__main__":
    main()

from __future__ import annotations

import argparse
import json
import re
import sys
import urllib.request
from html.parser import HTMLParser
from pathlib import Path
from typing import Any

from common import abs_path, dump_json, dump_text


FORBIDDEN_MARKETING_CLAIMS = [
    re.compile(r"\b#\s*1\b", re.IGNORECASE),
    re.compile(r"\bbest\b", re.IGNORECASE),
    re.compile(r"\bofficial\b", re.IGNORECASE),
    re.compile(r"\bguaranteed\b", re.IGNORECASE),
]


class MetaParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.title = ""
        self._in_title = False
        self.description = ""

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag.lower() == "title":
            self._in_title = True
        if tag.lower() == "meta":
            attr_map = {key.lower(): value or "" for key, value in attrs}
            if attr_map.get("name", "").lower() == "description" or attr_map.get("property", "").lower() == "og:description":
                self.description = self.description or attr_map.get("content", "")

    def handle_endtag(self, tag: str) -> None:
        if tag.lower() == "title":
            self._in_title = False

    def handle_data(self, data: str) -> None:
        if self._in_title:
            self.title += data


def load_listing(path: str | None) -> dict[str, Any]:
    if not path:
        return {}
    return json.loads(abs_path(path).read_text(encoding="utf-8"))


def load_competitors(args: argparse.Namespace) -> list[dict[str, Any]]:
    competitors: list[dict[str, Any]] = []
    if args.competitors_json:
        payload = json.loads(abs_path(args.competitors_json).read_text(encoding="utf-8"))
        competitors.extend(payload.get("competitors", payload if isinstance(payload, list) else []))
    for url in args.competitor_url:
        competitors.append({"url": url})
    return competitors


def fetch_metadata(url: str, timeout: int) -> dict[str, str]:
    request = urllib.request.Request(url, headers={"user-agent": "openclaw-cws-publisher/0.3"})
    with urllib.request.urlopen(request, timeout=timeout) as response:
        html = response.read(300_000).decode("utf-8", errors="ignore")
    parser = MetaParser()
    parser.feed(html)
    return {"title": " ".join(parser.title.split()), "description": " ".join(parser.description.split())}


def words(value: str) -> set[str]:
    return {part.lower() for part in re.findall(r"[a-zA-Z][a-zA-Z0-9]{2,}", value)}


def similarity(left: str, right: str) -> float:
    left_words = words(left)
    right_words = words(right)
    if not left_words or not right_words:
        return 0.0
    return len(left_words & right_words) / len(left_words | right_words)


def render_markdown(report: dict[str, Any]) -> str:
    lines = [
        "# CWS Competitor Check",
        "",
        f"Competitors: **{len(report['competitors'])}**",
        f"Blockers: **{len(report['blockers'])}**",
        f"Warnings: **{len(report['warnings'])}**",
        "",
        "| Name | URL | Similarity |",
        "| --- | --- | --- |",
    ]
    for competitor in report["competitors"]:
        lines.append(
            f"| {competitor.get('name') or competitor.get('title') or 'competitor'} | {competitor.get('url', '')} | {competitor.get('similarity', 0):.2f} |"
        )
    lines.extend(["", "## Blockers"])
    lines.extend([f"- {item}" for item in report["blockers"]] or ["No blockers."])
    lines.extend(["", "## Warnings"])
    lines.extend([f"- {item}" for item in report["warnings"]] or ["No warnings."])
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description="Run a lightweight CWS competitor/listing differentiation check.")
    parser.add_argument("--listing-json", help="Own CWS listing contract.")
    parser.add_argument("--competitors-json", help="JSON list or {competitors:[...]} file.")
    parser.add_argument("--competitor-url", action="append", default=[], help="Competitor/product URL to fetch. Repeatable.")
    parser.add_argument("--min-competitors", type=int, default=3)
    parser.add_argument("--fetch", action="store_true", help="Fetch competitor page metadata when title/description is missing.")
    parser.add_argument("--timeout", type=int, default=20)
    parser.add_argument("--json-out", help="Optional JSON report output path.")
    parser.add_argument("--markdown-out", help="Optional Markdown report output path.")
    args = parser.parse_args()

    listing = load_listing(args.listing_json)
    own_text = " ".join([listing.get("title", ""), listing.get("summary", ""), listing.get("detailed_description", "")])
    competitors = load_competitors(args)
    blockers: list[str] = []
    warnings: list[str] = []

    if len(competitors) < args.min_competitors:
        blockers.append(f"at least {args.min_competitors} competitors are required for a launch differentiation check")

    for pattern in FORBIDDEN_MARKETING_CLAIMS:
        if pattern.search(own_text):
            warnings.append(f"listing contains high-risk marketing claim matching {pattern.pattern}")

    enriched: list[dict[str, Any]] = []
    for competitor in competitors:
        item = dict(competitor)
        if args.fetch and item.get("url") and not item.get("title"):
            try:
                item.update(fetch_metadata(item["url"], args.timeout))
            except Exception as exc:  # noqa: BLE001 - competitor pages often block bots; report and continue.
                warnings.append(f"{item['url']}: failed to fetch competitor metadata: {exc}")
        competitor_text = " ".join([item.get("name", ""), item.get("title", ""), item.get("description", ""), item.get("positioning", "")])
        item["similarity"] = similarity(own_text, competitor_text)
        if item["similarity"] >= 0.72:
            warnings.append(f"{item.get('name') or item.get('url')}: listing may be too similar to a competitor")
        enriched.append(item)

    report = {
        "ok": not blockers,
        "listing": args.listing_json or "",
        "competitors": enriched,
        "blockers": blockers,
        "warnings": warnings,
    }
    if args.json_out:
        dump_json(args.json_out, report)
    if args.markdown_out:
        dump_text(args.markdown_out, render_markdown(report))
    print(json.dumps(report, indent=2, ensure_ascii=True))
    if blockers:
        sys.exit(1)


if __name__ == "__main__":
    main()

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any

from common import abs_path, dump_json, dump_text


REQUIRED_SCORE_FIELDS = [
    "product_clarity",
    "visual_trust",
    "evidence_integrity",
    "responsive_polish",
    "accessibility",
    "claim_alignment",
]


def load_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def score_value(surface: dict[str, Any], field: str) -> float | None:
    scores = surface.get("scores") or {}
    value = scores.get(field, surface.get(field))
    if isinstance(value, (int, float)):
        return float(value)
    return None


def validate_report(report: dict[str, Any], threshold: float) -> list[str]:
    blockers: list[str] = []
    surfaces = report.get("surfaces")
    if not isinstance(surfaces, list) or not surfaces:
        return ["design report must contain at least one surface"]

    for index, surface in enumerate(surfaces, start=1):
        name = surface.get("name") or f"surface #{index}"
        for field in REQUIRED_SCORE_FIELDS:
            value = score_value(surface, field)
            if value is None:
                blockers.append(f"{name}: missing {field} score")
            elif value < threshold:
                blockers.append(f"{name}: {field} score {value:g} is below {threshold:g}")
        screenshot = surface.get("screenshot") or surface.get("screenshot_path")
        if screenshot and not abs_path(screenshot).exists():
            blockers.append(f"{name}: screenshot does not exist: {screenshot}")
    return blockers


def validate_screenshot_metadata(paths: list[str]) -> list[str]:
    blockers: list[str] = []
    for raw_path in paths:
        path = abs_path(raw_path)
        if not path.exists():
            blockers.append(f"screenshot metadata does not exist: {path}")
            continue
        payload = load_json(path)
        source = payload.get("source")
        if source not in {"chrome-extension-popup", "browser-screenshot", "public-page-screenshot"}:
            blockers.append(f"{path}: unsupported screenshot source {source!r}")
        if not payload.get("captured_at"):
            blockers.append(f"{path}: missing captured_at")
        if source == "chrome-extension-popup" and not payload.get("extension_id"):
            blockers.append(f"{path}: popup screenshot metadata must include extension_id")
    return blockers


def render_markdown(report: dict[str, Any]) -> str:
    lines = [
        "# Design And UI Gate",
        "",
        f"Threshold: **{report['threshold']:g}/10**",
        f"Blockers: **{len(report['blockers'])}**",
        "",
        "## Blockers",
    ]
    lines.extend([f"- {item}" for item in report["blockers"]] or ["No blockers."])
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description="Validate recorded CWS design, UI, and UX critic scores.")
    parser.add_argument("--design-report", required=True, help="JSON report with surfaces and 0-10 critic scores.")
    parser.add_argument("--threshold", type=float, default=8.0, help="Minimum score per category.")
    parser.add_argument("--screenshot-metadata", action="append", default=[], help="Repeatable screenshot source metadata JSON.")
    parser.add_argument("--json-out", help="Optional JSON report output path.")
    parser.add_argument("--markdown-out", help="Optional Markdown report output path.")
    args = parser.parse_args()

    design_report_path = abs_path(args.design_report)
    source_report = load_json(design_report_path)
    blockers = [
        *validate_report(source_report, args.threshold),
        *validate_screenshot_metadata(args.screenshot_metadata),
    ]
    report = {
        "ok": not blockers,
        "design_report": str(design_report_path),
        "threshold": args.threshold,
        "blockers": blockers,
    }
    if args.json_out:
        dump_json(args.json_out, report)
    if args.markdown_out:
        dump_text(args.markdown_out, render_markdown(report))
    print(json.dumps(report, indent=2, ensure_ascii=True))
    if blockers:
        sys.exit(1)


if __name__ == "__main__":
    main()

from __future__ import annotations

import argparse
import json
import os
import re
import subprocess
from pathlib import Path
from typing import Iterable


def abs_path(value: str | Path) -> Path:
    return Path(value).expanduser().resolve()


def ensure_parent(path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)


def load_json(path: str | Path) -> dict:
    return json.loads(abs_path(path).read_text(encoding="utf-8"))


def dump_json(path: str | Path, payload: object) -> None:
    out = abs_path(path)
    ensure_parent(out)
    out.write_text(json.dumps(payload, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


def dump_text(path: str | Path, text: str) -> None:
    out = abs_path(path)
    ensure_parent(out)
    out.write_text(text.rstrip() + "\n", encoding="utf-8")


def run(
    cmd: list[str],
    *,
    cwd: str | Path | None = None,
    env: dict[str, str] | None = None,
    timeout: int | None = None,
) -> subprocess.CompletedProcess[str]:
    merged_env = os.environ.copy()
    if env:
        merged_env.update(env)
    return subprocess.run(
        cmd,
        cwd=str(cwd) if cwd else None,
        env=merged_env,
        text=True,
        capture_output=True,
        check=False,
        timeout=timeout,
    )


def slugify(value: str) -> str:
    lowered = value.strip().lower()
    lowered = re.sub(r"[^a-z0-9]+", "-", lowered)
    return lowered.strip("-")


def markdown_table(headers: list[str], rows: Iterable[Iterable[str]]) -> str:
    header_line = "| " + " | ".join(headers) + " |"
    divider = "| " + " | ".join(["---"] * len(headers)) + " |"
    body = ["| " + " | ".join(row) + " |" for row in rows]
    return "\n".join([header_line, divider, *body])


def build_parser(description: str) -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=description)
    parser.add_argument(
        "--repo-root",
        default=".",
        help="Project root. Defaults to cwd.",
    )
    return parser

from __future__ import annotations

import argparse
import json
import shlex
import subprocess
import sys
import time
from pathlib import Path
from typing import Any

from common import abs_path, dump_json, dump_text


DISCOVERED_NPM_GATES = [
    "check:cws",
    "check:public",
    "check:public:visual",
    "test:e2e:reviewer",
    "test:e2e",
]


def load_package_scripts(repo_root: Path) -> dict[str, str]:
    package_json = repo_root / "package.json"
    if not package_json.exists():
        return {}
    return json.loads(package_json.read_text(encoding="utf-8")).get("scripts") or {}


def detect_package_runner(repo_root: Path) -> str:
    if (repo_root / "pnpm-lock.yaml").exists():
        return "pnpm"
    if (repo_root / "yarn.lock").exists():
        return "yarn"
    return "npm"


def discover_commands(repo_root: Path) -> list[list[str]]:
    commands: list[list[str]] = []
    scripts = load_package_scripts(repo_root)
    runner = detect_package_runner(repo_root)
    for script in DISCOVERED_NPM_GATES:
        if script in scripts:
            commands.append([runner, script])
    reviewer_gate = repo_root / "scripts" / "reviewer_gate.py"
    if reviewer_gate.exists():
        commands.append(["python3", "scripts/reviewer_gate.py", "--repo-root", ".", "--skip-codex"])
    return commands


def run_command(repo_root: Path, command: list[str], timeout: int) -> dict[str, Any]:
    started = time.monotonic()
    try:
        result = subprocess.run(
            command,
            cwd=repo_root,
            text=True,
            capture_output=True,
            timeout=timeout,
            check=False,
        )
        return {
            "command": command,
            "returncode": result.returncode,
            "duration_seconds": round(time.monotonic() - started, 3),
            "stdout_tail": result.stdout[-4000:],
            "stderr_tail": result.stderr[-4000:],
        }
    except subprocess.TimeoutExpired as exc:
        return {
            "command": command,
            "returncode": 124,
            "duration_seconds": round(time.monotonic() - started, 3),
            "stdout_tail": (exc.stdout or "")[-4000:] if isinstance(exc.stdout, str) else "",
            "stderr_tail": f"timed out after {timeout}s",
        }


def render_markdown(report: dict[str, Any]) -> str:
    lines = [
        "# Local CWS E2E Gates",
        "",
        f"Repo: `{report['repo_root']}`",
        f"Commands: **{len(report['commands'])}**",
        f"Blockers: **{len(report['blockers'])}**",
        "",
    ]
    for item in report["results"]:
        status = "pass" if item["returncode"] == 0 else f"fail ({item['returncode']})"
        lines.extend(
            [
                f"## `{shlex.join(item['command'])}`",
                "",
                f"Status: **{status}** in {item['duration_seconds']}s",
                "",
            ]
        )
    if report["blockers"]:
        lines.extend(["## Blockers", *[f"- {item}" for item in report["blockers"]]])
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description="Run discovered or explicit repo-local CWS E2E gates.")
    parser.add_argument("--repo-root", default=".", help="Target extension repo root.")
    parser.add_argument("--command", action="append", default=[], help="Explicit command string. Repeatable.")
    parser.add_argument("--timeout", type=int, default=900, help="Timeout per command in seconds.")
    parser.add_argument("--dry-run", action="store_true", help="Only print commands without running them.")
    parser.add_argument("--json-out", help="Optional JSON report output path.")
    parser.add_argument("--markdown-out", help="Optional Markdown report output path.")
    args = parser.parse_args()

    repo_root = abs_path(args.repo_root)
    commands = [shlex.split(command) for command in args.command] if args.command else discover_commands(repo_root)
    blockers: list[str] = []
    results: list[dict[str, Any]] = []
    if not commands:
        blockers.append("no local E2E/reviewer gates were discovered; pass --command explicitly")

    if not args.dry_run:
        for command in commands:
            result = run_command(repo_root, command, args.timeout)
            results.append(result)
            if result["returncode"] != 0:
                blockers.append(f"{shlex.join(command)} failed with exit code {result['returncode']}")

    report = {
        "ok": not blockers,
        "repo_root": str(repo_root),
        "commands": commands,
        "dry_run": args.dry_run,
        "results": results,
        "blockers": blockers,
    }
    if args.json_out:
        dump_json(args.json_out, report)
    if args.markdown_out:
        dump_text(args.markdown_out, render_markdown(report))
    print(json.dumps(report, indent=2, ensure_ascii=True))
    if blockers:
        sys.exit(1)


if __name__ == "__main__":
    main()

from __future__ import annotations

import argparse
import json
import re
import sys
import zipfile
from pathlib import Path
from typing import Any

from common import abs_path, dump_json, dump_text


FORBIDDEN_PERMISSIONS = {"debugger", "tabs"}
FORBIDDEN_HOST_PERMISSIONS = {
    "<all_urls>",
    "https://chromewebstore.google.com/*",
    "https://chrome.google.com/webstore/*",
}
MANIFEST_COMPARE_FIELDS = [
    "manifest_version",
    "name",
    "version",
    "description",
    "permissions",
    "host_permissions",
    "optional_host_permissions",
    "content_scripts",
]
FORBIDDEN_CODE_PATTERNS = [
    ("eval", re.compile(r"\beval\s*\(")),
    ("Function constructor", re.compile(r"\bnew\s+Function\s*\(")),
    ("remote script tag", re.compile(r"<script[^>]+src=[\"']https?://", re.IGNORECASE)),
]
TEXT_SUFFIXES = {".html", ".js", ".mjs", ".cjs", ".json", ".css"}


def read_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def read_zip_manifest(zip_path: Path) -> dict[str, Any]:
    with zipfile.ZipFile(zip_path) as archive:
        with archive.open("manifest.json") as handle:
            return json.loads(handle.read().decode("utf-8"))


def default_manifest_value(field: str) -> Any:
    if field in {"permissions", "host_permissions", "optional_host_permissions", "content_scripts"}:
        return []
    return None


def normalized(value: Any) -> Any:
    if isinstance(value, list):
        return [normalized(item) for item in value]
    if isinstance(value, dict):
        return {key: normalized(value[key]) for key in sorted(value)}
    return value


def add_permission_findings(
    manifest: dict[str, Any],
    *,
    require_no_persistent_hosts: bool,
    blockers: list[str],
) -> None:
    permissions = set(manifest.get("permissions") or [])
    host_permissions = manifest.get("host_permissions") or []
    optional_host_permissions = manifest.get("optional_host_permissions") or []

    if manifest.get("manifest_version") != 3:
        blockers.append("manifest_version must be 3")

    for permission in sorted(permissions & FORBIDDEN_PERMISSIONS):
        blockers.append(f'forbidden permission "{permission}"')

    for host_permission in [*host_permissions, *optional_host_permissions]:
        if host_permission in FORBIDDEN_HOST_PERMISSIONS:
            blockers.append(f'forbidden host permission "{host_permission}"')

    if require_no_persistent_hosts and host_permissions:
        blockers.append("release ZIP requests persistent host_permissions; prefer activeTab plus scripting after user action")

    if require_no_persistent_hosts and optional_host_permissions:
        blockers.append("release ZIP requests optional_host_permissions; require a shipped opt-in flow and explicit justification")

    if not manifest.get("content_scripts") and "activeTab" in permissions and "scripting" not in permissions:
        blockers.append("activeTab dynamic capture requires scripting when no declarative content script is present")

    if require_no_persistent_hosts and manifest.get("content_scripts"):
        blockers.append("release ZIP declares content_scripts; this usually creates persistent host access and listing drift")


def add_manifest_drift_findings(
    source_manifest: dict[str, Any],
    zip_manifest: dict[str, Any],
    blockers: list[str],
) -> None:
    for field in MANIFEST_COMPARE_FIELDS:
        source_value = source_manifest.get(field, default_manifest_value(field))
        zip_value = zip_manifest.get(field, default_manifest_value(field))
        if normalized(source_value) != normalized(zip_value):
            blockers.append(f"release ZIP manifest {field} does not match source manifest")


def add_listing_findings(
    listing: dict[str, Any],
    manifest: dict[str, Any],
    blockers: list[str],
) -> None:
    permissions = manifest.get("permissions") or []
    host_permissions = manifest.get("host_permissions") or []
    optional_host_permissions = manifest.get("optional_host_permissions") or []
    host_justifications = listing.get("host_permission_justifications") or {}

    if manifest.get("name") and listing.get("title") and manifest["name"] != listing["title"]:
        blockers.append("listing title does not match manifest name")

    if manifest.get("description") and listing.get("summary") and manifest["description"] != listing["summary"]:
        blockers.append("listing summary does not match manifest description")

    if len(listing.get("summary") or "") > 132:
        blockers.append("listing summary exceeds Chrome Web Store 132-character limit")

    for permission in permissions:
        if not (listing.get("permission_justifications") or {}).get(permission):
            blockers.append(f"listing is missing permission justification for {permission}")

    for host_permission in [*host_permissions, *optional_host_permissions]:
        if not host_justifications.get(host_permission):
            blockers.append(f"listing is missing host permission justification for {host_permission}")

    if not host_permissions and not optional_host_permissions and host_justifications:
        blockers.append("listing has host_permission_justifications but the package requests no host permissions")

    detailed = listing.get("detailed_description") or ""
    if not host_permissions and not optional_host_permissions and not re.search(r"no persistent host permissions?", detailed, re.IGNORECASE):
        blockers.append('listing description must state "no persistent host permission(s)" when package has no host permissions')

    privacy = listing.get("privacy_practices") or {}
    if privacy.get("remote_code") is not False:
        blockers.append("privacy_practices.remote_code must be false")
    if privacy.get("limited_use_certification") is not True:
        blockers.append("privacy_practices.limited_use_certification must be true")


def add_code_findings(zip_path: Path, blockers: list[str], warnings: list[str]) -> None:
    with zipfile.ZipFile(zip_path) as archive:
        for info in archive.infolist():
            name = info.filename
            if name.endswith("/"):
                continue
            suffix = Path(name).suffix.lower()
            if suffix == ".map":
                warnings.append(f"source map included in release ZIP: {name}")
                continue
            if suffix not in TEXT_SUFFIXES:
                continue
            try:
                text = archive.read(info).decode("utf-8", errors="ignore")
            except OSError:
                continue
            for label, pattern in FORBIDDEN_CODE_PATTERNS:
                if pattern.search(text):
                    blockers.append(f"release ZIP contains forbidden {label}: {name}")


def render_markdown(report: dict[str, Any]) -> str:
    blockers = report["blockers"]
    warnings = report["warnings"]
    lines = [
        "# CWS Package Validation",
        "",
        f"ZIP: `{report['zip']}`",
        f"Manifest: `{report['manifest']['name']}` v{report['manifest']['version']}",
        "",
        f"Blockers: **{len(blockers)}**",
        f"Warnings: **{len(warnings)}**",
        "",
    ]
    lines.append("## Blockers")
    lines.extend([f"- {item}" for item in blockers] or ["No blockers."])
    lines.extend(["", "## Warnings"])
    lines.extend([f"- {item}" for item in warnings] or ["No warnings."])
    return "\n".join(lines)


def validate(args: argparse.Namespace) -> dict[str, Any]:
    zip_path = abs_path(args.zip)
    blockers: list[str] = []
    warnings: list[str] = []
    if not zip_path.exists():
        blockers.append(f"release ZIP does not exist: {zip_path}")
        manifest: dict[str, Any] = {}
    else:
        manifest = read_zip_manifest(zip_path)
        add_permission_findings(
            manifest,
            require_no_persistent_hosts=not args.allow_host_permissions,
            blockers=blockers,
        )
        add_code_findings(zip_path, blockers, warnings)

    if args.source_manifest:
        add_manifest_drift_findings(read_json(abs_path(args.source_manifest)), manifest, blockers)

    if args.listing_json:
        add_listing_findings(read_json(abs_path(args.listing_json)), manifest, blockers)

    return {
        "ok": not blockers,
        "zip": str(zip_path),
        "manifest": {
            "name": manifest.get("name", ""),
            "version": manifest.get("version", ""),
            "permissions": manifest.get("permissions") or [],
            "host_permissions": manifest.get("host_permissions") or [],
            "optional_host_permissions": manifest.get("optional_host_permissions") or [],
            "content_scripts_count": len(manifest.get("content_scripts") or []),
        },
        "blockers": blockers,
        "warnings": warnings,
    }


def main() -> None:
    parser = argparse.ArgumentParser(description="Validate the exact Chrome Web Store ZIP plus listing contract.")
    parser.add_argument("--zip", required=True, help="Release ZIP intended for CWS upload.")
    parser.add_argument("--source-manifest", help="Source manifest to compare against the ZIP manifest.")
    parser.add_argument("--listing-json", help="Repo-local docs/cws/listing.json contract.")
    parser.add_argument("--allow-host-permissions", action="store_true", help="Allow justified persistent/optional host permissions.")
    parser.add_argument("--json-out", help="Optional JSON report output path.")
    parser.add_argument("--markdown-out", help="Optional Markdown report output path.")
    args = parser.parse_args()

    report = validate(args)
    if args.json_out:
        dump_json(args.json_out, report)
    if args.markdown_out:
        dump_text(args.markdown_out, render_markdown(report))
    print(json.dumps(report, indent=2, ensure_ascii=True))
    if not report["ok"]:
        sys.exit(1)


if __name__ == "__main__":
    main()
